// Set scan mode based on trigger
let quickMode = '0';
let triggerSource = 'schedule';

if ($input.first()?.json?.headers) {
  // Came from a webhook
  triggerSource = 'webhook';
}

// Check which webhook triggered this
const nodeName = $input.first()?.json?.$node?.name || '';
if (nodeName.includes('Quick') || $('Webhook: Start Quick Scan')?.isExecuted) {
  quickMode = '1';
}

return [{ json: { quickMode, triggerSource, startedAt: new Date().toISOString() } }];

// Extract the job name from the K8s API response
const jobName = $input.first().json?.metadata?.name || 'unknown';
const namespace = 'scanning';
const startedAt = new Date().toISOString();
const quickMode = $('Set Scan Mode')?.first()?.json?.quickMode || $('Set Quick Mode')?.first()?.json?.quickMode || '0';

return [{
  json: {
    jobName,
    namespace,
    startedAt,
    quickMode,
    status: 'Running',
    pollCount: 0,
    maxPolls: 120
  }
}];

const job = $input.first().json;
const conditions = job?.status?.conditions || [];
const prevData = $('Extract Job Name').first()?.json || $('Wait 15s').first()?.json || {};

let status = 'Running';
let done = false;

for (const c of conditions) {
  if (c.type === 'Complete' && c.status === 'True') {
    status = 'Complete';
    done = true;
    break;
  }
  if (c.type === 'Failed' && c.status === 'True') {
    status = 'Failed';
    done = true;
    break;
  }
}

const pollCount = (prevData.pollCount || 0) + 1;
if (pollCount >= (prevData.maxPolls || 120)) {
  status = 'Timeout';
  done = true;
}

return [{
  json: {
    jobName: prevData.jobName || job?.metadata?.name,
    namespace: prevData.namespace || 'scanning',
    startedAt: prevData.startedAt,
    quickMode: prevData.quickMode,
    status,
    done,
    pollCount,
    maxPolls: prevData.maxPolls || 120,
    completedAt: done ? new Date().toISOString() : null,
    active: job?.status?.active || 0,
    succeeded: job?.status?.succeeded || 0,
    failed: job?.status?.failed || 0
  }
}];

const findings = $input.first().json?.results || [];
const jobData = $('Check Job Status').first()?.json || {};

// Severity breakdown
const byServerity = { Critical: 0, High: 0, Medium: 0, Low: 0, Info: 0 };
const byScanner = {};
const recentFindings = [];
const now = new Date();
const oneDayAgo = new Date(now.getTime() - 24 * 60 * 60 * 1000);

for (const f of findings) {
  const sev = f.severity || 'Info';
  byServerity[sev] = (byServerity[sev] || 0) + 1;

  // Extract scanner from tags
  const tags = f.tags || [];
  for (const t of tags) {
    if (['nuclei', 'sqlmap', 'ffuf', 'xss', 'grype', 'xsstrike'].includes(t)) {
      byScanner[t] = (byScanner[t] || 0) + 1;
    }
  }

  // Recent findings (last 24h)
  const created = new Date(f.created || f.date || 0);
  if (created > oneDayAgo) {
    recentFindings.push({
      id: f.id,
      title: f.title,
      severity: f.severity,
      scanner: tags.find(t => ['nuclei','sqlmap','ffuf','xss','grype','xsstrike'].includes(t)) || 'unknown'
    });
  }
}

const total = findings.length;
const critHigh = (byServerity.Critical || 0) + (byServerity.High || 0);

// Priority distribution from tags
const byPriority = { critical: 0, high: 0, medium: 0, low: 0 };
for (const f of findings) {
  for (const t of (f.tags || [])) {
    const m = String(t).match(/^priority-(\d+)$/);
    if (m) {
      const p = parseInt(m[1]);
      if (p >= 80) byPriority.critical++;
      else if (p >= 60) byPriority.high++;
      else if (p >= 40) byPriority.medium++;
      else byPriority.low++;
    }
  }
}

return [{
  json: {
    scanResult: {
      jobName: jobData.jobName,
      status: jobData.status,
      quickMode: jobData.quickMode === '1',
      startedAt: jobData.startedAt,
      completedAt: jobData.completedAt,
      duration: jobData.startedAt && jobData.completedAt
        ? Math.round((new Date(jobData.completedAt) - new Date(jobData.startedAt)) / 1000)
        : null
    },
    summary: {
      totalFindings: total,
      criticalAndHigh: critHigh,
      bySeverity: byServerity,
      byScanner,
      byPriority,
      newLast24h: recentFindings.length
    },
    recentFindings: recentFindings.slice(0, 20),
    timestamp: new Date().toISOString()
  }
}];

const jobData = $('Check Job Status').first()?.json || $input.first()?.json || {};
const errorInfo = $('Create Scan Job').first()?.json || {};

return [{
  json: {
    error: true,
    status: jobData.status || 'Error',
    jobName: jobData.jobName || 'unknown',
    message: `Scan ${jobData.status || 'failed'}: job=${jobData.jobName || 'N/A'}`,
    pollCount: jobData.pollCount || 0,
    failed: jobData.failed || 0,
    errorDetails: errorInfo.message || errorInfo.reason || null,
    timestamp: new Date().toISOString()
  }
}];

// Log error to n8n execution history (notification sink)
const err = $input.first().json;
console.log(`[VOC ALERT] Scan failed: ${err.message}`);
// To wire real notifications: replace this with an HTTP Request to your
// Slack webhook, Discord webhook, or email API.
// The URL should be set as an n8n credential or environment variable.
return [{ json: { notified: true, channel: 'execution-log', ...err } }];

const findingsResp = $('Get Findings (Dashboard)').first()?.json || {};
const testsResp = $('Get Test History').first()?.json || {};

const findings = findingsResp.results || [];
const tests = testsResp.results || [];

// --- Severity breakdown ---
const bySeverity = { Critical: 0, High: 0, Medium: 0, Low: 0, Info: 0 };
const byScanner = {};
const byTarget = {};

for (const f of findings) {
  const sev = f.severity || 'Info';
  bySeverity[sev] = (bySeverity[sev] || 0) + 1;
  const tags = f.tags || [];
  for (const t of tags) {
    if (['nuclei','sqlmap','ffuf','xss','grype','xsstrike','crawler'].includes(t)) {
      byScanner[t] = (byScanner[t] || 0) + 1;
    }
    if (['juice-shop','dvwa','web-dvwa'].includes(t)) {
      byTarget[t] = (byTarget[t] || 0) + 1;
    }
  }
}

// --- Priority distribution ---
const byPriority = { critical: 0, high: 0, medium: 0, low: 0, unscored: 0 };
for (const f of findings) {
  let scored = false;
  for (const t of (f.tags || [])) {
    const m = String(t).match(/^priority-(\d+)$/);
    if (m) {
      scored = true;
      const p = parseInt(m[1]);
      if (p >= 80) byPriority.critical++;
      else if (p >= 60) byPriority.high++;
      else if (p >= 40) byPriority.medium++;
      else byPriority.low++;
    }
  }
  if (!scored) byPriority.unscored++;
}

// --- Top critical findings ---
const topFindings = findings
  .filter(f => f.severity === 'Critical' || f.severity === 'High')
  .slice(0, 15)
  .map(f => ({
    id: f.id,
    title: f.title,
    severity: f.severity,
    cve: f.cve || null,
    verified: f.verified || false,
    active: f.active,
    date: f.date,
    tags: f.tags || []
  }));

// --- Recent scan history ---
const scanHistory = tests.slice(0, 10).map(t => ({
  id: t.id,
  title: t.title,
  scanType: t.scan_type_name || t.test_type_name,
  updated: t.updated,
  findingCount: t.finding_count || 0
}));

// --- MTTR estimate ---
const now = new Date();
const thirtyDaysAgo = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);
let closedCount = 0;
let totalResolutionDays = 0;
for (const f of findings) {
  if (f.is_mitigated && f.mitigated) {
    const created = new Date(f.date || f.created);
    const mitigated = new Date(f.mitigated);
    if (mitigated > thirtyDaysAgo) {
      closedCount++;
      totalResolutionDays += (mitigated - created) / (1000 * 60 * 60 * 24);
    }
  }
}
const mttr = closedCount > 0 ? Math.round(totalResolutionDays / closedCount * 10) / 10 : null;

const dashboard = {
  pipelineStatus: 'operational',
  lastUpdated: new Date().toISOString(),
  findings: {
    total: findings.length,
    totalActive: findingsResp.count || findings.length,
    bySeverity,
    byScanner,
    byTarget,
    byPriority,
    criticalAndHigh: (bySeverity.Critical || 0) + (bySeverity.High || 0)
  },
  metrics: {
    mttrDays: mttr,
    closedLast30d: closedCount,
    scannerCount: Object.keys(byScanner).length,
    targetCount: Object.keys(byTarget).length
  },
  topFindings,
  scanHistory
};

return [{ json: dashboard }];

// Health check: ping DefectDojo, prioritization service, and scan targets
const checks = [];

async function checkUrl(name, url) {
  try {
    const resp = await this.helpers.request({ url, method: 'GET', timeout: 5000, resolveWithFullResponse: true });
    return { name, status: 'healthy', statusCode: resp.statusCode || 200 };
  } catch (e) {
    return { name, status: 'unhealthy', error: e.message || String(e) };
  }
}

return [{
  json: {
    timestamp: new Date().toISOString(),
    checks: [
      { name: 'defectdojo', url: 'http://defectdojo-django.voc-core.svc.cluster.local/' },
      { name: 'prioritization', url: 'http://prioritization-service.voc-core.svc.cluster.local:8000/healthz' },
      { name: 'juice-shop', url: 'http://juice-shop.targets.svc.cluster.local:3000/' },
      { name: 'dvwa', url: 'http://dvwa.targets.svc.cluster.local/' }
    ]
  }
}];

// Aggregate health check results
const dd = $('Ping DefectDojo').first()?.json;
const prio = $('Ping Prioritization').first()?.json;
const juice = $('Ping Juice Shop').first()?.json;
const dvwa = $('Ping DVWA').first()?.json;

function toStatus(resp, name) {
  if (!resp) return { name, status: 'unknown' };
  if (resp.error || resp.message?.includes('ECONNREFUSED')) {
    return { name, status: 'unhealthy', error: resp.message || resp.error };
  }
  return { name, status: 'healthy' };
}

const results = [
  toStatus(dd, 'DefectDojo'),
  toStatus(prio, 'Prioritization Service'),
  toStatus(juice, 'Juice Shop'),
  toStatus(dvwa, 'DVWA')
];

const allHealthy = results.every(r => r.status === 'healthy');

// Store in static data for dashboard access
const staticData = $getWorkflowStaticData('global');
staticData.lastHealthCheck = {
  timestamp: new Date().toISOString(),
  overall: allHealthy ? 'healthy' : 'degraded',
  services: results
};

console.log(`[VOC Health] ${allHealthy ? 'All services healthy' : 'Some services unhealthy: ' + results.filter(r => r.status !== 'healthy').map(r => r.name).join(', ')}`);

return [{ json: staticData.lastHealthCheck }];

const findings = $input.first().json?.results || [];
const out = [];

for (const f of findings) {
  const tags = (f.tags || []).map(t => String(t));
  const pTag = tags.find(t => t.startsWith('priority-'));
  const priority = pTag ? parseInt(pTag.split('-')[1], 10) : null;
  out.push({
    json: {
      id: f.id,
      title: f.title,
      severity: f.severity,
      cve: f.cve || null,
      priority,
      verified: f.verified || false,
      tags,
      date: f.date,
      endpoints: (f.endpoints || []).slice(0, 3)
    }
  });
}

return out.length > 0 ? out : [{ json: { id: null, title: 'No active findings', severity: 'Info', priority: 0 } }];

// CRITICAL PRIORITY — Log to execution history.
// To wire real alerting, replace this with an HTTP Request node
// pointing to your Slack/Discord webhook or PagerDuty.
const f = $input.first().json;
console.log(`[VOC CRITICAL] Finding #${f.id}: ${f.title} (severity=${f.severity}, priority=${f.priority})`);
return [{ json: { ...f, alertLevel: 'critical', notified: true, channel: 'execution-log' } }];

// HIGH PRIORITY — Log to execution history.
const f = $input.first().json;
console.log(`[VOC HIGH] Finding #${f.id}: ${f.title} (severity=${f.severity}, priority=${f.priority})`);
return [{ json: { ...f, alertLevel: 'high', notified: true, channel: 'execution-log' } }];

// MEDIUM / LOW — Log only, no notification.
const f = $input.first().json;
console.log(`[VOC INFO] Finding #${f.id}: ${f.title} (priority=${f.priority})`);
return [{ json: { ...f, alertLevel: 'info', notified: false } }];
